# Verify K_{7,7} is triangle-free and maximal
n = 14
left = list(range(7))
right = list(range(7, 14))

edges = [(i, j) for i in left for j in right]

# Check triangle-free
adj = {i: set() for i in range(n)}
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

def has_triangle():
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return True
    return False

print("Has triangle:", has_triangle())

# Check maximal: for every non-edge, adding it creates a triangle
non_edges = [(u,v) for u in range(n) for v in range(u+1, n) if v not in adj[u]]
print("Number of non-edges:", len(non_edges))

def adding_creates_triangle(u,v):
    # check if there exists w such that u-w and v-w are edges
    common = adj[u] & adj[v]
    return len(common) > 0

all_maximal = True
for u,v in non_edges:
    if not adding_creates_triangle(u,v):
        print("Non-edge", u, v, "does not create triangle when added")
        all_maximal = False
        break

print("All non-edges create triangle:", all_maximal)
print("Graph is maximal triangle-free:", not has_triangle() and all_maximal)
